function validate([n, edges]) {
  if (n < 2 || n > 100000) return 'n must be between 2 and 100000.';
  if (edges.length !== n - 1) return 'There must be exactly n - 1 edges.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (u < 0 || u >= n || v < 0 || v >= n) return 'Edge endpoints must be between 0 and n - 1.';
    if (u === v) return 'An edge cannot join a node to itself.';
    const a = find(u), b = find(v);
    if (a === b) return 'Ignoring directions, the edges must form a tree (no cycles or repeats).';
    root[a] = b;
  }
  return null;
}

