function minEdgeReversals(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push([v, 0]);
    graph[v].push([u, 1]);
  }

  const parent = new Array(n).fill(-1);
  const reversed = new Array(n).fill(0);
  const order = [0];
  parent[0] = 0;
  let rootCost = 0;
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const [next, cost] of graph[node]) {
      if (parent[next] === -1) {
        parent[next] = node;
        reversed[next] = cost;
        rootCost += cost;
        order.push(next);
      }
    }
  }

  const answer = new Array(n).fill(0);
  answer[0] = rootCost;
  for (let i = 1; i < order.length; i++) {
    const node = order[i];
    answer[node] = answer[parent[node]] + (reversed[node] === 1 ? -1 : 1);
  }
  return answer;
}

