function minEdgeReversals(n, edges) {
  // For every start node, grow the set of reached nodes one edge at a time,
  // counting each edge that has to be crossed against its direction.
  const answer = [];
  for (let start = 0; start < n; start++) {
    const reached = new Set([start]);
    let flips = 0, grew = true;
    while (grew) {
      grew = false;
      for (const [u, v] of edges) {
        if (reached.has(u) && !reached.has(v)) { reached.add(v); grew = true; }
        else if (reached.has(v) && !reached.has(u)) { reached.add(u); flips++; grew = true; }
      }
    }
    answer.push(flips);
  }
  return answer;
}

